// MODO APRENDIZAJE. LearnWorlds no publica el formato exacto de sus eventos, así
// que este nodo busca el email, el nombre y el tipo de evento en los lugares
// donde suelen venir, y solo cambia la etapa en Zoho si reconoce las dos cosas.
// Lo que no reconoce NO toca Zoho: se envía por correo al equipo para que se vea
// el formato real y se ajuste este nodo.
//
// Mientras LEARNING_MODE sea true, el equipo recibe también el detalle de los
// primeros eventos del día aunque se hayan reconocido. Cuando el formato esté
// confirmado, ponlo en false.
const LEARNING_MODE = true;
const LEARNING_EMAILS_PER_DAY = 10;
const UNRECOGNIZED_EMAILS_PER_DAY = 20;

const raw = $input.first().json;
const b = raw.body ?? raw;

const get = (object, path) =>
  path.split('.').reduce((o, key) => (o && typeof o === 'object' ? o[key] : undefined), object);
const pick = (paths) => {
  for (const path of paths) {
    const value = get(b, path);
    if (value !== undefined && value !== null && String(value).trim() !== '') return String(value).trim();
  }
  return '';
};
const clip = (value, max) =>
  String(value ?? '').replace(/[\u0000-\u0008\u000b-\u001f\u007f]+/g, ' ').trim().slice(0, max);

const EMAIL = /^[^\s@]{1,64}@[^\s@]{1,255}\.[^\s@]{2,}$/;
const email = clip(
  pick(['data.user.email', 'user.email', 'data.student.email', 'data.learner.email', 'data.userEmail', 'data.email', 'email']),
  254,
).toLowerCase();
const eventType = clip(pick(['type', 'event', 'event_type', 'eventType', 'trigger', 'data.type', 'name']), 120);

let first = clip(pick(['data.user.first_name', 'data.user.firstName', 'user.first_name', 'data.first_name', 'first_name']), 100);
let last = clip(pick(['data.user.last_name', 'data.user.lastName', 'user.last_name', 'data.last_name', 'last_name']), 100);
if (!first && !last) {
  const full = clip(pick(['data.user.name', 'user.name', 'data.name', 'name']), 100);
  const parts = full.split(/\s+/).filter(Boolean);
  if (parts.length > 1) {
    first = parts.slice(0, -1).join(' ');
    last = parts[parts.length - 1];
  } else if (parts.length === 1) {
    last = parts[0];
  }
}

// De evento a etapa del ciclo de vida. El orden importa: las palabras de compra
// van antes que "complet", porque "pago completado" no es "curso completado".
const t = eventType.toLowerCase();
let stage = '';
if (/unenrol|cancel|refund|revok|expire|suspend|chargeback|dispute|delete/.test(t)) stage = '';
else if (/purchas|order|payment|paid|subscri|bought|enrol/.test(t)) stage = 'Enrolled';
else if (/complet|certificat|graduat/.test(t)) stage = 'Completed';

const recognized = EMAIL.test(email) && stage !== '';

// ----- contadores del aviso al equipo (datos del flujo; solo con el flujo activo) -----
const store = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (!store.lw || store.lw.date !== today) store.lw = { date: today, learning: 0, unrecognized: 0 };
let notify = false;
if (!recognized) {
  if (store.lw.unrecognized < UNRECOGNIZED_EMAILS_PER_DAY) {
    store.lw.unrecognized += 1;
    notify = true;
  }
} else if (LEARNING_MODE && store.lw.learning < LEARNING_EMAILS_PER_DAY) {
  store.lw.learning += 1;
  notify = true;
}

// El detalle crudo se recorta y se enmascara: solo sirve para ver el formato.
let rawText = '';
try {
  rawText = JSON.stringify(b, null, 2).slice(0, 4000);
} catch (e) {
  rawText = String(b).slice(0, 4000);
}

return [
  {
    json: {
      recognized,
      notify,
      stage,
      eventType,
      email: EMAIL.test(email) ? email : '',
      first,
      last,
      raw: rawText,
    },
  },
];

// Prepara la actualización del contacto en Zoho según lo que respondió la búsqueda.
//  - Si el contacto YA existe: solo se actualiza la etapa. NUNCA se tocan nombre ni
//    apellido, para no pisar lo que la persona escribió en el formulario.
//  - Si NO existe (compró sin haber pasado por una landing page): se crea con el
//    nombre que mande LearnWorlds. Zoho exige apellido.
const event = $('Reconocer evento').first().json;
const search = $input.first().json || {};

const found = Array.isArray(search.data) && search.data.length > 0 ? search.data[0] : null;
const now = new Date().toISOString();
const slug = String(event.eventType || 'event').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '').slice(0, 60);

const record = {
  Email: event.email,
  YB_Lifecycle: event.stage,
  Lifecycle_Updated_At: now,
  YB_Event: `learnworlds_${slug}`,
};

if (!found) {
  record.Last_Name = event.last || event.first || event.email.split('@')[0];
  if (event.first && event.last) record.First_Name = event.first;
}

return [{ json: { record, existing: Boolean(found) } }];

// Zoho responde 200/202 aunque rechace el registro (por ejemplo un campo que no
// existe). Sin esta comprobación el flujo diría "guardado" sin haber guardado nada.
// Si falla, el flujo termina con error y la web le pide a la persona que reintente.
const response = $input.first().json;
const result = Array.isArray(response.data) ? response.data[0] : null;

if (!result || result.status !== 'success' || !result.details || !result.details.id) {
  const why = result ? [result.code, result.message].filter(Boolean).join(' · ') : 'respuesta vacía';
  throw new Error('Zoho no guardó el contacto: ' + why);
}

return [{ json: { id: result.details.id, action: result.action || '' } }];

// Correo al equipo con el detalle de un evento de LearnWorlds, para ver el formato
// real de lo que se recibe. Todo va escapado: es contenido que llega de fuera.
const cfg = (name, fallback) => {
  try {
    return $vars[name] || fallback;
  } catch (e) {
    return fallback;
  }
};
const TEAM = String(cfg('YB_TEAM_EMAIL', '')).trim();
if (!TEAM) return [];

const NAVY = '#031f3c';
const SAND = '#b8a27a';
const IVORY = '#f6f3ec';

const e = $('Reconocer evento').first().json;
const esc = (value) =>
  String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const oneLine = (value) => String(value ?? '').replace(/[\r\n\u0000-\u001f]+/g, ' ').trim();

const status = e.recognized
  ? `Recognized: the contact was moved to "${e.stage}" in Zoho CRM.`
  : 'NOT recognized: Zoho CRM was not changed. Either the email or the event type could not be read from this payload.';

const rows = [
  ['Event type', e.eventType],
  ['Email found', e.email],
  ['Stage', e.stage],
].filter(([, value]) => value && String(value).trim() !== '');

const table = `<table width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 16px 0">${rows
  .map(
    ([key, value]) =>
      `<tr><td style="padding:8px 12px 8px 0;border-bottom:1px solid #efeadf;width:110px;vertical-align:top;font-size:11px;letter-spacing:1.2px;text-transform:uppercase;color:#8a7448">${esc(key)}</td>` +
      `<td style="padding:8px 0;border-bottom:1px solid #efeadf;vertical-align:top;font-size:14px;color:#1f2d3d">${esc(value)}</td></tr>`,
  )
  .join('')}</table>`;

const html = `<!doctype html><html><body style="margin:0;padding:0;background:${IVORY}">
<table width="100%" cellpadding="0" cellspacing="0" style="background:${IVORY};padding:32px 0"><tr><td align="center">
<table width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#ffffff;border:1px solid #e4dfd3">
<tr><td style="background:${NAVY};padding:28px 36px">
<p style="margin:0;font-family:Arial,sans-serif;font-size:11px;letter-spacing:4px;text-transform:uppercase;color:${SAND}">YB University</p>
<h1 style="margin:10px 0 0 0;font-family:Georgia,serif;font-weight:normal;font-size:26px;line-height:1.2;color:#ffffff">LearnWorlds event</h1>
</td></tr>
<tr><td style="padding:32px 36px 28px 36px;font-family:Arial,sans-serif">
<p style="margin:0 0 16px 0;font-size:14px;line-height:1.6;color:#1f2d3d">${esc(status)}</p>
${table}
<p style="margin:0 0 8px 0;font-size:11px;letter-spacing:1.2px;text-transform:uppercase;color:#8a7448">Raw payload (trimmed)</p>
<pre style="margin:0;padding:12px;background:#f6f3ec;font-size:12px;line-height:1.5;color:#1f2d3d;white-space:pre-wrap;word-break:break-word">${esc(e.raw)}</pre>
</td></tr>
<tr><td style="background:${SAND};height:4px;font-size:0;line-height:0">&nbsp;</td></tr>
</table></td></tr></table></body></html>`;

return [{ json: { to: TEAM, subject: `[YB LearnWorlds] ${oneLine(e.eventType || 'unrecognized event').slice(0, 80)}`, html } }];
